INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('d452bd8b-7967-5e36-8388-d341c4645ea1', 'workspace', 'ws_choir_fitness_049', 'June life and choir memo', 0, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00', '{"title":{"title":[{"type":"text","text":{"content":"June life and choir memo"}}]}}', NULL, NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('3ae9d595-e11a-53a6-aa4e-49df6f6b78c5', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"June included three combined rehearsals preparing Farewell and Jasmine Flower, with breath marks on the scores."}}]}', 0, 0, 0, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('5b94aad2-eb3b-5e5b-a622-8006fb99c1ae', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"June 4 rehabilitation follow-up: right-knee stair discomfort about 2/10, with no notable change on level-ground walking."}}]}', 0, 0, 1, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('9cd4d652-4d1b-5316-9af4-bf1ac167edaf', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Common May and June activities were riverside walks, home activities, choir vocal practice, and occasional swimming."}}]}', 0, 0, 2, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('e5da4579-7c06-52a7-9538-72a19277bd9a', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Three June rehearsals record song sections, placement, and mid-session rest; the second moved to Row A."}}]}', 0, 0, 3, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('47fe4e1c-5954-5f42-a136-ce2e6d370814', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The cultural center east entrance is near a bus stop; the west entrance has steps and the north wood floor retains water after rain."}}]}', 0, 0, 4, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('e8ce9491-c3cf-5e3b-b9bd-fa9c2dece229', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Two-hour rehearsals usually rest ten minutes after the first hour; one June rehearsal ended early for piano tuning."}}]}', 0, 0, 5, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('28a7b25e-9e5c-57e7-bfb6-7b7bcd19e67e', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The rehabilitation booking stays in the private mailbox; the choir directory stores only names, phones, and sections."}}]}', 0, 0, 6, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('e7b9b1ef-3ca9-51f6-a777-62995e95089e', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Ms. Evelyn Hart emails in June focused on songs, venues, placement, and rehearsal times; replies focused on scores."}}]}', 0, 0, 7, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('c6e9b2a7-eb8f-5112-bb15-7b3caf51dde8', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Two mid-June nights were short; morning energy ratings were 5 and 6."}}]}', 0, 0, 8, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('68b5b393-a3e9-5c08-88f2-da16f250a189', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"On June 21 the cultural center opened a first-floor air-conditioned rest area; attendees were reminded to bring water."}}]}', 0, 0, 9, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('79902fc2-783b-5465-bae2-e14b8e00eed7', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The cultural center east entrance has a ramp; the first-floor small classroom has a piano and twenty backed chairs."}}]}', 0, 0, 10, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('29af49b0-f40e-5234-89e5-574aaf7d098d', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Performance shoe candidates are old black cloth shoes and new soft-soled shoes; replace old laces before July."}}]}', 0, 0, 11, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('414f017b-f74b-525c-ace9-9271528f4bd1', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"June family expenses included utilities, transport to mothers clinic, and two choir score deposits; receipts are in the drawer."}}]}', 0, 0, 12, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('0c87484a-1877-5941-8ef5-75b299a0f883', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Maya Zhou maintains the personal calendar; choir notices usually come from Ms. Evelyn Harts emails."}}]}', 0, 0, 13, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('0ff0f7df-bf9a-507e-b194-cd6adf0b824d', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The wristband finished syncing on the evening of June 16, about two hours later than usual."}}]}', 0, 0, 14, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('48ec50d2-30ca-5125-a1c1-25095a7f97ea', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The June journal stores weather, rehearsal songs, and energy by date, with a few notes from paper slips."}}]}', 0, 0, 15, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('93edd270-fabd-506f-ae18-b7c170dcc85a', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The June 4 follow-up records subjective pain, stair context, and the next observation date."}}]}', 0, 0, 16, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('0ed33039-a48b-50e7-8323-bd94efdf07b0', NULL, 'd452bd8b-7967-5e36-8388-d341c4645ea1', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The July plan is not yet on the page; current content covers late May through June."}}]}', 0, 0, 17, '2026-06-25T09:00:00+08:00', '2026-06-25T09:00:00+08:00');
INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('b7d18420-61ce-4a8d-bf53-a8930ca77e14', 'workspace', 'ws_choir_fitness_049', 'June songs and rehearsal notes', 0, '2026-06-18T10:20:00+08:00', '2026-06-28T21:10:00+08:00', '{"title":{"title":[{"type":"text","text":{"content":"June songs and rehearsal notes"}}]}}', NULL, NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('c4e2f9a1-7896-4c38-a5d7-c74de55b2301', NULL, 'b7d18420-61ce-4a8d-bf53-a8930ca77e14', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The breath point in bar 3 of Farewell section two is marked blue; the soprano section releases the final note lightly."}}]}', 0, 0, 0, '2026-06-18T10:21:00+08:00', '2026-06-18T10:21:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('0ef43bd7-7412-44df-94e0-429ef66cd7ae', NULL, 'b7d18420-61ce-4a8d-bf53-a8930ca77e14', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The first four bars of Jasmine Flower need a piano tempo check; Ms. Evelyn Hart suggests hearing the demo before the weekend."}}]}', 0, 0, 1, '2026-06-18T10:22:00+08:00', '2026-06-18T10:22:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('adf2d2f0-fb75-47d9-bcf7-09bcd36f104d', NULL, 'b7d18420-61ce-4a8d-bf53-a8930ca77e14', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"On June 23 the entrance order changed: sopranos enter from stage right and Maya Zhou is third."}}]}', 0, 0, 2, '2026-06-23T21:05:00+08:00', '2026-06-23T21:05:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('de0beaef-29d4-4622-a030-d83e597ceec5', NULL, 'b7d18420-61ce-4a8d-bf53-a8930ca77e14', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The activity-room piano was tuned on June 19; noise from two bass keys is gone."}}]}', 0, 0, 3, '2026-06-24T08:10:00+08:00', '2026-06-24T08:10:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('b1312105-b8db-4df0-b873-cbedf40d5d20', NULL, 'b7d18420-61ce-4a8d-bf53-a8930ca77e14', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The old score-folder cover was fixed with clear tape; a spare pencil is in the inner pocket."}}]}', 0, 0, 4, '2026-06-26T12:30:00+08:00', '2026-06-26T12:30:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('51ced719-5096-49e9-98a7-9c33cf3510fb', NULL, 'b7d18420-61ce-4a8d-bf53-a8930ca77e14', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"After the last June rehearsal, the section leader asked everyone to bring a black folder next time."}}]}', 0, 0, 5, '2026-06-28T21:10:00+08:00', '2026-06-28T21:10:00+08:00');
INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('c895b62e-e09c-443d-b501-44af2842f2ea', 'workspace', 'ws_choir_fitness_049', 'Family and community matters', 0, '2026-06-12T08:30:00+08:00', '2026-06-29T18:45:00+08:00', '{"title":{"title":[{"type":"text","text":{"content":"Family and community matters"}}]}}', NULL, NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('d2fba691-31e6-45be-b4e6-96f4b78cf366', NULL, 'c895b62e-e09c-443d-b501-44af2842f2ea', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Mothers June 9 clinic visit is complete; the next visit is tentatively in September, with lab reports in the blue folder."}}]}', 0, 0, 0, '2026-06-12T08:31:00+08:00', '2026-06-12T08:31:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('3c931d3f-767a-4026-b14f-d96e70da6fbf', NULL, 'c895b62e-e09c-443d-b501-44af2842f2ea', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The library volunteer shift was completed on June 13 and three returned books were logged."}}]}', 0, 0, 1, '2026-06-14T09:15:00+08:00', '2026-06-14T09:15:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('cc63c0d7-7e38-45f8-b0fb-596b0f1fbc4f', NULL, 'c895b62e-e09c-443d-b501-44af2842f2ea', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The July utility bill is expected before the 10th; the paper bill goes to the first-floor mailbox."}}]}', 0, 0, 2, '2026-06-20T11:00:00+08:00', '2026-06-20T11:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('8b37ca0f-b0a2-4e86-a31d-b1a65425a73d', NULL, 'c895b62e-e09c-443d-b501-44af2842f2ea', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Two osmanthus cakes remained from the tea social and were given to the next-door neighbor."}}]}', 0, 0, 3, '2026-06-21T17:40:00+08:00', '2026-06-21T17:40:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('5944f9ee-fafc-443d-a135-0f60bd6591db', NULL, 'c895b62e-e09c-443d-b501-44af2842f2ea', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The community service center payment queue was about fifteen minutes on June 25; the east elevator was available."}}]}', 0, 0, 4, '2026-06-25T12:05:00+08:00', '2026-06-25T12:05:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('2db958ee-22a8-4a9a-af28-690103b50f80', NULL, 'c895b62e-e09c-443d-b501-44af2842f2ea', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"June photos are organized into three albums for family, choir, and community activities."}}]}', 0, 0, 5, '2026-06-29T18:45:00+08:00', '2026-06-29T18:45:00+08:00');
